CREATE TABLE notifications (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, kind VARCHAR(32) NOT NULL, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, link VARCHAR(255) NULL, conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, read_at DATETIME(6) NULL, email_status VARCHAR(12) NOT NULL DEFAULT 'skipped', email_to VARCHAR(254) NULL, attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), locked_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY notifications_feed_idx (user_id,created_at), KEY notifications_mail_idx (email_status,next_attempt_at), CONSTRAINT notifications_email_ck CHECK (email_status IN ('pending','processing','sent','failed','skipped')), CONSTRAINT notifications_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci